import{_ as s,l as i,o as e,c as n,v as o,p as l,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"SSA 析构与 φ 消除","description":"","frontmatter":{"title":"SSA 析构与 φ 消除","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ssa-destruction.md","filePath":"cs/ssa-destruction.md","lastUpdated":1789023840000}'),h={name:"cs/ssa-destruction.md"};function S(u,a,_,m,A,E){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="ssa-析构与-φ-消除" tabindex="-1">SSA 析构与 φ 消除 <a class="header-anchor" href="#ssa-析构与-φ-消除" aria-label="Permalink to &quot;SSA 析构与 φ 消除&quot;">​</a></h1><div class="epigraph"><p>机器没有 φ。析构在每条前驱边末尾插入传送，把 SSA 名合并回可着色的存储。错序会引入交换问题。</p><footer>—— 据 Briggs, Harvey and Simpson, Practical Considerations for SSA Destruction；Cytron et al.；Appel 整理</footer></div><p>上一课<a href="/cs/ssa-construction-cytron">Cytron 构造</a>插入 φ。后端<a href="/cs/regalloc-color">寄存器分配</a>前通常离开 SSA。缺口是<strong>析构</strong>：φ 变成 <code>mov</code>。经典坑：并行 φ 的交换（<code>x,y = y,x</code>）需要临时。本课钉边拷贝与关键边，不写着色。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>φ 语义是「沿进入边同时选择」。实现：在前驱块末 <code>x3 = x1</code> 或 <code>x3 = x2</code>。若同一块两个 φ 交叉赋值，串行 <code>mov</code> 会覆盖。缺口是<strong>并行拷贝的串行化</strong>，不是 DF。</p><p>关键边：无唯一插入点，先拆块。</p><h3 id="析构不是「删掉-φ-不管」" tabindex="-1">析构不是「删掉 φ 不管」 <a class="header-anchor" href="#析构不是「删掉-φ-不管」" aria-label="Permalink to &quot;析构不是「删掉 φ 不管」&quot;">​</a></h3><p>随便删 φ 会丢失汇合。必须有拷贝或让分配器同时分配 φ 与操作数到同一寄存器（合并）。</p><p><span class="marginnote">Briggs 等 SSA destruction。Sreedhar 的方法减少拷贝。LLVM 在分配中处理 PHI。本课常规：先拆 φ 再着色，或 SSA 上着色（Chordal）点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>拆关键边。为每个 φ 与每个前驱生成拷贝。对块末并行拷贝图：找交换环，用临时或 swap。再跑拷贝传播。</p>',11)),(e(),l(p,null,{default:t(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PHI%5B%22%CF%86%22%5D%20--%3E%20CRIT%5B%22%E6%8B%86%E5%85%B3%E9%94%AE%E8%BE%B9%22%5D%0A%20%20CRIT%20--%3E%20MOV%5B%22%E5%89%8D%E9%A9%B1%E6%9C%AB%E4%BC%A0%E9%80%81%22%5D%0A%20%20MOV%20--%3E%20SER%5B%22%E5%B9%B6%E8%A1%8C%E6%8B%B7%E8%B4%9D%E4%B8%B2%E8%A1%8C%E5%8C%96%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与<a href="/cs/coalescing-splitting">合并</a> 后课：析构产生的 <code>mov</code> 正是合并的输入。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>未定义的 φ 操作数（未初始化变量）须按语言填毒值或拒绝。不要在析构后还当 SSA 做 SCCP。</p><p>异常边：前驱是 invoke 的 unwind，插入点在专用边块。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Briggs 着色。后课默认：φ 在后端前变成传送。下一课自然循环：许多循环优化要在 SSA 上认循环，构造/析构顺序是「优化在 SSA，分配前析构」。</p><p>也不把析构当 DCE。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>析构：φ → 前驱边拷贝；关键边先拆。</li><li>并行赋值要处理交换。</li><li>与随后的合并、着色衔接。</li><li>出处：Cytron et al.；Briggs, Harvey and Simpson；Appel。</li></ul>',9))])}const C=s(h,[["render",S]]);export{f as __pageData,C as default};
